		} else {
			echo '<p class="center">' . error_string( ERROR_ACCESS_DENIED ) . '</p>';
			echo '<p class="center">';
			print_bracket_link( helper_mantis_url( 'main_page.php' ), lang_get( 'proceed' ) );
			echo '</p>';
		}
	}
	exit;
}

